query.base:
TS metrics-gcp.cloudrun.otel-*
// Services only: cloud_run_job documents have no service_name
| WHERE `metrics.run.googleapis.com/request_latencies` IS NOT NULL
  AND resource.attributes.service_name IS NOT NULL
  // Successful requests only (same scope as the latency SLO); 5xx/timeouts are covered by the 5xx error rate rule
  AND attributes.response_code_class IN ("2xx", "3xx")
// Exclude streaming / long-lived connection services (SSE, WebSocket, MCP), whose latency equals connection lifetime
// | WHERE resource.attributes.service_name NOT IN ("my-streaming-service")
// Percentiles must use the ::exponential_histogram cast (never ::tdigest, never PERCENTILE of *_OVER_TIME)
// COUNT of the histogram = number of measured requests (used as the volume guard)
| STATS
    latency_p95_ms = PERCENTILE(`metrics.run.googleapis.com/request_latencies`::exponential_histogram, 95),
    latency_p50_ms = PERCENTILE(`metrics.run.googleapis.com/request_latencies`::exponential_histogram, 50),
    measured_requests = COUNT(`metrics.run.googleapis.com/request_latencies`::exponential_histogram)
  BY resource.attributes.project_id, resource.attributes.location, resource.attributes.service_name
